    description: "A deliberate extra step before verification starts: confirm rights and spec compliance up front, in plain language, not buried behind a Terms of Service link. Framing it as \"step 1 of 2\" keeps it reading as part of the upload flow instead of a legal detour that stalls someone.",
    html: "<div style=\"width:660px;height:829px;background:#fff;border-radius:22px;box-shadow:0 1px 2px rgba(26,21,38,.05),0 6px 14px rgba(26,21,38,.05),0 20px 40px rgba(26,21,38,.07),0 44px 80px rgba(26,21,38,.06);overflow:hidden;position:relative\">\n  <div style=\"position:absolute;inset:0;padding:26px 30px;filter:blur(1.5px);opacity:.5\">\n    <div style=\"display:flex;justify-content:center;margin-bottom:26px\"><div style=\"display:flex;gap:4px;padding:4px;background:#F4F2F8;border:1px solid #E8E6EE;border-radius:999px\"><div style=\"width:56px;height:24px;border-radius:999px\"></div><div style=\"width:56px;height:24px;border-radius:999px\"></div><div style=\"width:64px;height:24px;border-radius:999px\"></div><div style=\"width:56px;height:24px;border-radius:999px;background:linear-gradient(135deg,#7A17B8,#5B0C93)\"></div></div></div>\n    <div style=\"display:grid;grid-template-columns:216px 1fr;gap:24px\">\n      <div style=\"display:flex;flex-direction:column;gap:18px\">\n        <div style=\"display:flex;flex-direction:column;gap:8px\"><div style=\"width:66px;height:12px;border-radius:4px;background:#E4E1EB\"></div><div style=\"height:52px;border:1px solid #E8E6EE;border-radius:12px\"></div><div style=\"height:52px;border:1px solid #E8E6EE;border-radius:12px\"></div><div style=\"height:52px;border:1px solid #E8E6EE;border-radius:12px\"></div></div>\n        <div style=\"display:flex;flex-direction:column;gap:8px\"><div style=\"width:66px;height:12px;border-radius:4px;background:#E4E1EB\"></div><div style=\"height:52px;background:#FEF6F5;border:1px solid #F3C9C4;border-left:3px solid #E0483E;border-radius:12px\"></div></div>\n        <div style=\"display:flex;flex-direction:column;gap:8px\"><div style=\"width:66px;height:12px;border-radius:4px;background:#E4E1EB\"></div><div style=\"height:52px;background:#F4FCF7;border:1px solid #BFE6CE;border-left:3px solid #1F9D55;border-radius:12px\"></div><div style=\"height:52px;background:#F4FCF7;border:1px solid #BFE6CE;border-left:3px solid #1F9D55;border-radius:12px\"></div></div>\n      </div>\n      <div style=\"display:flex;flex-direction:column;gap:14px\"><div style=\"height:300px;border:1px solid #E8E6EE;border-radius:16px\"></div><div style=\"height:96px;border:1px solid #E8E6EE;border-radius:16px\"></div></div>\n    </div>\n  </div>\n  <div style=\"position:absolute;inset:0;background:rgba(26,21,38,.34);backdrop-filter:blur(2px)\"></div>\n  <div style=\"position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:404px;background:#fff;border-radius:20px;box-shadow:0 2px 6px rgba(26,21,38,.12),0 14px 30px rgba(26,21,38,.16),0 40px 80px rgba(26,21,38,.22);overflow:hidden\">\n    <div style=\"height:4px;background:linear-gradient(90deg,#5B0C93,#A855F7)\"></div>\n    <div style=\"padding:26px 28px 24px\">\n      <div style=\"font:600 9.5px/1 'Plus Jakarta Sans',sans-serif;letter-spacing:.1em;text-transform:uppercase;color:#7A17B8\">Step 1 of 2</div>\n      <div style=\"font:700 22px/1.25 'Plus Jakarta Sans',sans-serif;color:#1A1526;margin-top:8px;text-wrap:pretty\">Terms of service &amp; verification</div>\n      <div style=\"margin-top:16px;height:132px;border-radius:14px;background:linear-gradient(160deg,#F7F1FD,#EFE7FA);border:1px dashed #D3BDEE;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:6px\">\n        <svg width=\"26\" height=\"26\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#B57DE0\" stroke-width=\"1.6\"><rect x=\"3\" y=\"4\" width=\"18\" height=\"16\" rx=\"3\"/><circle cx=\"8.5\" cy=\"9.5\" r=\"1.6\"/><path d=\"M4 17l5-4.5 4 3.5 3-2.5 4 3.5\"/></svg>\n        <span style=\"font:600 10px/1 'Plus Jakarta Sans',sans-serif;color:#9A7CC0\">Illustration placeholder</span>\n      </div>\n      <div style=\"margin-top:16px;font:500 11.5px/1.7 'Plus Jakarta Sans',sans-serif;color:#4A4458;text-wrap:pretty\">By continuing you confirm you hold the rights to every asset in this upload, and that the artwork matches the approved contract specification. Files are checked against media-owner requirements before they reach production.</div>\n      <div style=\"margin-top:14px;display:flex;align-items:flex-start;gap:9px;padding:11px 12px;background:#FAF9FC;border:1px solid #E8E6EE;border-radius:10px\">\n        <div style=\"width:15px;height:15px;border-radius:4px;background:linear-gradient(135deg,#7A17B8,#5B0C93);display:flex;align-items:center;justify-content:center;flex:none\"><svg width=\"10\" height=\"10\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"3.4\"><path d=\"M6 12.5l4 4 8-9\"/></svg></div>\n        <span style=\"font:600 10.5px/1.45 'Plus Jakarta Sans',sans-serif;color:#4A4458\">I have read and accept the verification terms.</span>\n      </div>\n      <div style=\"margin-top:20px;display:flex;gap:10px\">\n        <div style=\"flex:1;text-align:center;padding:12px 0;border-radius:999px;border:1.5px solid #E0DCE8;font:600 12.5px/1 'Plus Jakarta Sans',sans-serif;color:#4A4458\">Decline</div>\n        <div style=\"flex:1;text-align:center;padding:12px 0;border-radius:999px;background:linear-gradient(135deg,#7A17B8,#5B0C93);font:700 12.5px/1 'Plus Jakarta Sans',sans-serif;color:#fff\">Agree &amp; continue</div>\n      </div>\n    </div>\n  </div>\n</div>",
